def glom_cli(target, spec, indent, debug, inspect, scalar):
    """Command-line interface to the glom library, providing nested data
    access and data restructuring with the power of Python.
    """
    if debug or inspect:
        stdin_open = not sys.stdin.closed
        spec = Inspect(spec,
                       echo=inspect,
                       recursive=inspect,
                       breakpoint=inspect and stdin_open,
                       post_mortem=debug and stdin_open)

    try:
        result = glom.glom(target, spec)
    except GlomError as ge:
        print(f'{ge.__class__.__name__}: {ge}')
        return 1

    if scalar:
        # For scalar output, print without quotes or trailing newline
        if result is None:
            # Handle None values gracefully
            print("", end='')
        elif isinstance(result, (dict, list, tuple)):
            # For complex objects, use JSON formatting but without newlines
            print(json.dumps(result, separators=(',', ':')), end='')
        else:
            # For simple scalar values, print directly
            print(result, end='')
    else:
        if not indent:
            indent = None
        print(json.dumps(result, indent=indent, sort_keys=True))
    return
